/* New biology questions for the thinnest official small titles.
   They are added after the existing questions, so saved answers keep their positions.
   biology-question-map.js says which set each one belongs to, using the "set" field order below. */
(function () {
  var Q = [
    /* ── Biological importance of weak interactions (index 0 in biology-syllabus LESSON_SETS) ── */
    { set: 0, question: "Gentle heating separates the two strands of a DNA double helix without breaking either strand. Why?", options: ["The sugar-phosphate backbone is held by hydrogen bonds", "The strands are joined by peptide bonds, which are heat-sensitive", "The strands are joined by hydrogen bonds, while each backbone is covalent", "The bases are joined to the sugars by ionic bonds", "Heating removes the phosphate groups from each strand"], correct: 2, solution: "Complementary bases pair through hydrogen bonds, which are weak and break with moderate heat. The phosphodiester bonds of each backbone are covalent and stay intact." },
    { set: 0, question: "Ice floats on liquid water because:", options: ["Hydrogen bonds hold water molecules further apart in ice than in the liquid", "Covalent bonds in water lengthen when it freezes", "Ice contains dissolved air in every crystal", "Water molecules lose their polarity when frozen", "Ice has a greater mass per molecule than liquid water"], correct: 0, solution: "In ice, each molecule forms a regular network of hydrogen bonds that spaces the molecules further apart. Ice is therefore less dense than liquid water." },
    { set: 0, question: "In a soluble globular protein, non-polar side chains are mostly found in the interior. What is the main reason?", options: ["They form disulfide bridges with water", "They are attracted to the peptide backbone by ionic bonds", "They are too large to fit on the surface", "The hydrophobic effect excludes them from contact with water", "Ribosomes place them inside during translation"], correct: 3, solution: "Non-polar groups cannot hydrogen-bond with water. Clustering them away from water is energetically favourable, and this hydrophobic effect is a major force in protein folding." },
    { set: 0, question: "A positively charged lysine side chain and a negatively charged aspartate side chain lie close together in a folded protein. Which interaction forms between them?", options: ["Peptide bond", "Ionic interaction (salt bridge)", "Disulfide bridge", "Glycosidic bond", "Phosphodiester bond"], correct: 1, solution: "Opposite charges on side chains attract each other, forming a non-covalent ionic interaction, also called a salt bridge." },
    { set: 0, question: "Which statement about van der Waals interactions is correct?", options: ["They form only between ions with opposite charges", "They are stronger than covalent bonds", "They require a hydrogen atom bonded to oxygen or nitrogen", "They occur only in liquid water", "They arise from temporary dipoles and act only at very short distances"], correct: 4, solution: "Van der Waals interactions come from temporary fluctuations in electron distribution. Each is very weak and only acts when atoms are very close together." },
    { set: 0, question: "Why is it useful for most enzymes to bind their substrates through weak interactions?", options: ["The binding is reversible, so the products can be released", "Weak interactions provide the energy to make ATP", "It makes the enzyme part of the product", "It prevents the enzyme from changing shape", "It allows the enzyme to work without an active site"], correct: 0, solution: "Weak interactions allow specific but temporary binding. If binding were permanent, the enzyme could not release the products and act on new substrate molecules." },
    { set: 0, question: "Which of the following is NOT a weak (non-covalent) interaction?", options: ["Hydrogen bond", "Hydrophobic interaction", "Disulfide bridge", "Salt bridge", "Van der Waals interaction"], correct: 2, solution: "A disulfide bridge is a covalent bond between the sulfur atoms of two cysteine residues. The other four are non-covalent." },
    { set: 0, question: "A single hydrogen bond is far weaker than a covalent bond. How can hydrogen bonds still stabilise large structures such as DNA and proteins?", options: ["They turn into covalent bonds after a few seconds", "Many of them act together, so their combined effect is large", "They are stronger inside the cell than in water", "They use energy from ATP to stay intact", "They form only once in each molecule, in a key position"], correct: 1, solution: "Each hydrogen bond is weak, but a macromolecule contains a very large number of them. Together they give stability, while individual bonds can still break and reform." },
    { set: 0, question: "When table salt dissolves in water, Na⁺ and Cl⁻ ions stay apart mainly because:", options: ["Water breaks covalent bonds inside each ion", "The ions react with water to form new molecules", "Water molecules are non-polar and repel the ions", "Salt ions become uncharged in solution", "Polar water molecules surround each ion and shield its charge"], correct: 4, solution: "The partial charges on water molecules are attracted to the ions and form a hydration shell around each one, which reduces the attraction between Na⁺ and Cl⁻." },
    { set: 0, question: "An antibody binds tightly and specifically to its antigen, yet the two can separate again. Which feature of the binding best explains this?", options: ["Many non-covalent interactions between complementary surfaces", "A single peptide bond between antibody and antigen", "Disulfide bridges between antibody and antigen", "Phosphodiester bonds formed by the antibody", "A covalent bond that is cut by ATP"], correct: 0, solution: "Antibody-antigen binding depends on many weak interactions across complementary surfaces. Together they give high specificity and affinity, while the binding stays reversible." },

    /* ── Cell theory and cell size (index 3) ── */
    { set: 3, question: "Which statement belongs to classical cell theory?", options: ["All cells contain a nucleus", "All cells arise from pre-existing cells", "Cells can arise spontaneously from non-living matter", "All living organisms are made of many cells", "Viruses are the smallest type of cell"], correct: 1, solution: "Cell theory states that all organisms are made of one or more cells, the cell is the basic unit of life, and all cells come from pre-existing cells. Bacteria have no nucleus, and many organisms are unicellular." },
    { set: 3, question: "The phrase “omnis cellula e cellula” (every cell comes from a cell) is associated with:", options: ["Gregor Mendel", "Charles Darwin", "Robert Hooke", "Louis Pasteur", "Rudolf Virchow"], correct: 4, solution: "Rudolf Virchow popularised this statement in 1855, adding the idea that new cells come only from existing cells." },
    { set: 3, question: "Which pairing of scientists and contribution is correct?", options: ["Schleiden and Schwann: proposed that plants and animals are made of cells", "Watson and Crick: first observed cells in cork", "Mendel and Darwin: invented the electron microscope", "Hooke and Virchow: discovered the structure of DNA", "Schleiden and Mendel: described natural selection"], correct: 0, solution: "Matthias Schleiden studied plants and Theodor Schwann studied animals. Their work in the 1830s led to the idea that all organisms are made of cells." },
    { set: 3, question: "Robert Hooke used the word “cells” in the 17th century after observing:", options: ["Human red blood cells", "Bacteria in pond water", "Thin slices of cork", "Sperm cells", "Onion cell nuclei"], correct: 2, solution: "Hooke examined cork under an early microscope and saw small box-like compartments, which were the walls of dead plant cells." },
    { set: 3, question: "A cube-shaped cell grows from a side of 1 µm to a side of 2 µm. What happens to its surface area to volume ratio?", options: ["It doubles, from 3 to 6 µm⁻¹", "It stays the same at 6 µm⁻¹", "It falls to a quarter, from 8 to 2 µm⁻¹", "It halves, from 6 to 3 µm⁻¹", "It increases eight times"], correct: 3, solution: "At 1 µm: area 6 µm², volume 1 µm³, ratio 6. At 2 µm: area 24 µm², volume 8 µm³, ratio 3. The ratio halves." },
    { set: 3, question: "What is the main reason most cells remain microscopic?", options: ["Larger cells cannot contain DNA", "A low surface area to volume ratio would limit exchange with the surroundings", "Cell membranes cannot be made longer than 1 µm", "Ribosomes work only in very small cells", "Oxygen cannot pass through a large nucleus"], correct: 1, solution: "As a cell grows, its volume increases faster than its surface. A large cell would have too little membrane to exchange enough nutrients, gases and waste." },
    { set: 3, question: "What is the typical length of a bacterial cell?", options: ["1–5 nm", "10–50 mm", "1–5 mm", "100–500 µm", "1–5 µm"], correct: 4, solution: "Most bacteria are about 1 to 5 µm long, which is roughly ten times smaller than a typical eukaryotic cell." },
    { set: 3, question: "How many micrometres are there in 1 millimetre?", options: ["1,000", "10", "100", "10,000", "1,000,000"], correct: 0, solution: "1 mm = 10⁻³ m and 1 µm = 10⁻⁶ m, so 1 mm = 1,000 µm." },
    { set: 3, question: "Which list is in order of increasing size?", options: ["Bacterium, ribosome, human ovum, red blood cell", "Ribosome, bacterium, red blood cell, human ovum", "Red blood cell, ribosome, human ovum, bacterium", "Human ovum, red blood cell, bacterium, ribosome", "Ribosome, red blood cell, bacterium, human ovum"], correct: 1, solution: "Approximate sizes: ribosome 20–30 nm, bacterium 1–5 µm, red blood cell 7–8 µm, human ovum about 100 µm." },
    { set: 3, question: "Which feature increases the surface area of an intestinal cell without greatly increasing its volume?", options: ["A larger nucleus", "A thicker cell wall", "Microvilli", "A central vacuole", "More ribosomes"], correct: 2, solution: "Microvilli are tiny folds of the plasma membrane. They greatly increase the area available for absorption while adding very little volume." },
    { set: 3, question: "On a micrograph at a magnification of ×1,000, a red blood cell measures 7 mm across. What is its actual diameter?", options: ["0.7 µm", "70 µm", "7 nm", "7 µm", "700 µm"], correct: 3, solution: "Actual size = image size / magnification. 7 mm / 1,000 = 0.007 mm, which is 7 µm." },
    { set: 3, question: "Which of the following cannot be seen individually with a standard light microscope?", options: ["A human ovum", "A ribosome", "A plant cell", "A large bacterium", "The nucleus of a human cheek cell"], correct: 1, solution: "A light microscope resolves objects down to about 0.2 µm. A ribosome is only about 20–30 nm across, so it requires an electron microscope." },

    /* ── Life cycles, sexual and asexual reproduction (index 14) ── */
    { set: 14, question: "Apart from mutations, how are offspring produced by asexual reproduction related to their parent?", options: ["They carry half of the parent's DNA", "They are genetically identical to the parent", "They carry new combinations of alleles from crossing over", "They always have twice as many chromosomes", "They are always haploid"], correct: 1, solution: "Asexual reproduction involves one parent and no fusion of gametes, so the offspring form a clone of the parent unless a mutation occurs." },
    { set: 14, question: "What is the main evolutionary advantage of sexual reproduction?", options: ["It produces offspring faster than asexual reproduction", "It requires only one parent", "It uses less energy than asexual reproduction", "It generates genetic variation among offspring", "It prevents mutations from occurring"], correct: 3, solution: "Crossing over, independent assortment and random fertilisation create new combinations of alleles. This variation gives natural selection more to act on." },
    { set: 14, question: "Yeast and Hydra can form a small outgrowth that develops into a new individual. This type of reproduction is called:", options: ["Conjugation", "Meiosis", "Budding", "Fertilisation", "Binary fusion"], correct: 2, solution: "In budding, a new organism grows as an outgrowth from the parent and may then separate. It is a form of asexual reproduction." },
    { set: 14, question: "In honeybees, males (drones) develop from unfertilised eggs. This process is known as:", options: ["Parthenogenesis", "Conjugation", "Regeneration", "Double fertilisation", "Alternation of generations"], correct: 0, solution: "Parthenogenesis is the development of an embryo from an unfertilised egg. Drones are therefore haploid, while females develop from fertilised eggs." },
    { set: 14, question: "In the human life cycle, which cells are haploid?", options: ["All body cells", "Zygotes", "Embryonic stem cells", "Muscle and nerve cells only", "Only the gametes"], correct: 4, solution: "Humans have a diplontic life cycle. The organism is diploid, meiosis produces haploid gametes, and fertilisation restores diploidy in the zygote." },
    { set: 14, question: "In the moss life cycle, the dominant, longer-lived green plant is the:", options: ["Diploid sporophyte", "Haploid gametophyte", "Triploid endosperm", "Diploid zygote", "Diploid seed"], correct: 1, solution: "In mosses, the familiar green plant is the haploid gametophyte. The diploid sporophyte grows on it and depends on it. In ferns and seed plants, the sporophyte is dominant." },
    { set: 14, question: "In plants with alternation of generations, how are spores and gametes produced?", options: ["Spores by meiosis, gametes by mitosis", "Spores by mitosis, gametes by meiosis", "Both by meiosis", "Both by mitosis", "Spores by fertilisation, gametes by budding"], correct: 0, solution: "The diploid sporophyte makes haploid spores by meiosis. These grow into a haploid gametophyte, which is already haploid and so makes gametes by mitosis." },
    { set: 14, question: "In a haplontic life cycle, as in many fungi and some algae, which stage is the only diploid one?", options: ["The adult organism", "The gamete", "The spore", "The zygote", "The mycelium"], correct: 3, solution: "In a haplontic cycle, the organism is haploid. Gametes fuse to form a diploid zygote, which immediately undergoes meiosis." },
    { set: 14, question: "A planarian flatworm cut into pieces can give rise to several complete individuals. Which process does this show?", options: ["Conjugation", "Double fertilisation", "Meiosis", "Sexual selection", "Fragmentation and regeneration"], correct: 4, solution: "Each fragment regenerates the missing parts and forms a complete organism. This is a form of asexual reproduction." },
    { set: 14, question: "Potato tubers and strawberry runners are examples of:", options: ["Sexual reproduction", "Pollination", "Vegetative propagation", "Parthenogenesis", "Seed dispersal"], correct: 2, solution: "Vegetative propagation forms new plants from parts of the parent, without gametes. The offspring are genetically identical to the parent." },
    { set: 14, question: "Aphids often reproduce asexually when conditions are stable, and sexually as conditions worsen. What is the most likely advantage of this pattern?", options: ["Asexual reproduction allows rapid growth, while sexual reproduction provides variation for changing conditions", "Sexual reproduction is faster when food is scarce", "Asexual reproduction produces more genetic variation", "Sexual reproduction prevents all mutations", "Asexual reproduction requires two parents, which are easier to find in good conditions"], correct: 0, solution: "Clones spread quickly when an existing genotype suits the environment. When conditions change, the variation produced by sexual reproduction increases the chance that some offspring will survive." },
    { set: 14, question: "Earthworms carry both male and female reproductive organs but usually mate with another individual. Such organisms are described as:", options: ["Haploid", "Asexual", "Hermaphrodites that cross-fertilise", "Parthenogenetic", "Sterile"], correct: 2, solution: "A hermaphrodite has both male and female organs. Cross-fertilisation between two individuals still mixes genetic material and keeps variation in the population." },
    { set: 14, question: "How does a spore differ from a gamete?", options: ["A spore is always diploid and a gamete is always haploid", "A spore must fuse with another cell, while a gamete develops alone", "A spore contains no DNA", "Gametes are found only in plants", "A spore can develop into a new organism without fusing with another cell"], correct: 4, solution: "A gamete must fuse with another gamete to form a zygote. A spore can grow directly into a new individual, with no fusion." },

    /* ── Human genetics: mono- and multifactorial transmission (index 21) ── */
    { set: 21, question: "Which of these conditions is multifactorial?", options: ["Huntington's disease", "Cystic fibrosis", "Haemophilia A", "Type 2 diabetes", "Sickle cell anaemia"], correct: 3, solution: "Type 2 diabetes depends on several genes together with environmental factors such as diet and physical activity. The other four are caused by mutations in a single gene." },
    { set: 21, question: "What does it mean to say a human trait is multifactorial?", options: ["It depends on several genes and environmental factors", "It is controlled by one gene with many alleles", "It appears only in males", "It is carried on mitochondrial DNA", "It is not influenced by genes at all"], correct: 0, solution: "Multifactorial traits result from the combined action of many genes and the environment. They do not follow simple Mendelian ratios." },
    { set: 21, question: "If a polygenic trait such as adult height is plotted for a large population, the graph is most likely to show:", options: ["Two separate peaks", "Three distinct classes in a 1:2:1 ratio", "A bell-shaped (normal) distribution", "A single value shared by everyone", "A 3:1 ratio of tall to short"], correct: 2, solution: "Many genes with small additive effects, plus environmental influences, produce continuous variation. The result is an approximately normal distribution." },
    { set: 21, question: "Monozygotic twins share almost identical DNA. If they show less than 100% concordance for a disease, what is the best conclusion?", options: ["The disease is caused by a single dominant allele", "The disease is entirely non-genetic", "The disease is X-linked", "The twins must be dizygotic", "Factors other than DNA sequence, such as the environment, contribute to the disease"], correct: 4, solution: "With nearly identical genomes, differences between the twins point to non-genetic factors. A trait can still have a genetic component, as shown when concordance is higher in monozygotic than dizygotic twins." },
    { set: 21, question: "A trait is controlled by three unlinked genes with equal additive effects, where each capital-letter allele adds the same amount. How many phenotypic classes can the cross AaBbCc × AaBbCc produce?", options: ["3", "7", "8", "9", "27"], correct: 1, solution: "Offspring can carry from 0 to 6 capital-letter alleles. Since each allele adds the same amount, there are 7 possible phenotypic classes." },
    { set: 21, question: "In the cross AaBbCc × AaBbCc, with three unlinked genes, what is the probability that a child has the genotype AABBCC?", options: ["1/8", "1/16", "1/27", "1/32", "1/64"], correct: 4, solution: "The probability of a homozygous dominant genotype for each gene is 1/4. For three independent genes: 1/4 × 1/4 × 1/4 = 1/64." },
    { set: 21, question: "In families affected by a multifactorial disorder, how does the risk usually change with the degree of relationship to the affected person?", options: ["It is always exactly 25% for all relatives", "It is the same for all relatives", "It is highest in first-degree relatives and falls in more distant relatives", "It is higher in distant relatives than in siblings", "It is zero in all relatives"], correct: 2, solution: "Closer relatives share more alleles, and often more of their environment. So the risk is highest in first-degree relatives and drops quickly with more distant relationships." },
    { set: 21, question: "According to the threshold model of multifactorial disease, when does the disease appear?", options: ["When a person's combined genetic and environmental liability exceeds a critical level", "When a person inherits one specific dominant allele", "As soon as one environmental factor is present", "Only when both parents are affected", "Only in people with an extra chromosome"], correct: 0, solution: "Liability is spread continuously across a population, but the disease shows up only above a threshold. This explains why some multifactorial traits are either present or absent." },
    { set: 21, question: "Phenylketonuria is caused by mutations in a single gene, but a low-phenylalanine diet prevents most of its effects. What does this show?", options: ["The disease is not genetic", "The diet repairs the mutated gene", "Phenylketonuria is multifactorial and polygenic", "The environment can change the phenotype even for a single-gene disorder", "The mutation disappears after childhood"], correct: 3, solution: "The genotype stays the same, but limiting phenylalanine prevents the harmful build-up. Phenotype depends on both genotype and environment." },
    { set: 21, question: "Average adult height increased in many countries during the 20th century, much faster than the gene pool could have changed. The most likely main cause is:", options: ["A new dominant allele for height", "Improved nutrition and health", "An increase in the mutation rate", "A change in the number of human chromosomes", "Inactivation of the X chromosome"], correct: 1, solution: "Gene pools change slowly over generations. A rapid rise in a polygenic trait across a population points to environmental causes such as better nutrition and healthcare." },
    { set: 21, question: "Heritability of a trait is best defined as the:", options: ["Probability that a child inherits a specific allele", "Number of genes that control the trait", "Percentage of an individual's trait caused by their genes", "Share of phenotypic variation in a population that is due to genetic differences", "Rate at which a mutation spreads in a population"], correct: 3, solution: "Heritability describes variation within a population. It does not say what percentage of one individual's trait comes from genes." },
    { set: 21, question: "A couple has one child with cleft lip, a multifactorial malformation, and no other relatives are affected. What is the most accurate statement about their next child's risk?", options: ["It is exactly 25%, as in recessive inheritance", "It is exactly 50%, as in dominant inheritance", "It is the same as for any couple in the population", "It is zero, because the event cannot happen twice", "It is above the population risk, but not fixed by a Mendelian ratio"], correct: 4, solution: "Having an affected child suggests the family carries some liability. The recurrence risk is above the population risk, and is estimated from data rather than from a 1:4 or 1:2 ratio." },

    /* ── Prokaryotic DNA and eukaryotic chromosome structure (index 19) ── */
    { set: 19, question: "What is the usual form of the main chromosome in a bacterium such as E. coli?", options: ["Several linear molecules in a nucleus", "A single circular DNA molecule in the nucleoid", "A single-stranded RNA molecule", "A linear DNA molecule with telomeres", "Many circular molecules enclosed in a membrane"], correct: 1, solution: "Most bacteria have one circular chromosome, which lies in a region of the cytoplasm called the nucleoid. It is not enclosed by a membrane." },
    { set: 19, question: "Compared with a bacterial chromosome, a eukaryotic chromosome usually has:", options: ["A single origin of replication", "No proteins associated with it", "Multiple origins of replication", "A circular structure", "No centromere"], correct: 2, solution: "Long linear eukaryotic chromosomes need many origins to finish replication in time. A bacterial chromosome usually has a single origin." },
    { set: 19, question: "A nucleosome consists of:", options: ["DNA wrapped around a core of eight histone proteins", "RNA wrapped around a ribosome", "Two sister chromatids held by a centromere", "A plasmid inside a protein coat", "A pair of homologous chromosomes"], correct: 0, solution: "A nucleosome is the basic packaging unit of chromatin. About 147 base pairs of DNA wrap around a histone octamer." },
    { set: 19, question: "Histones bind strongly to DNA mainly because:", options: ["Histones are negatively charged, like DNA", "They form covalent bonds with every base", "They are made of nucleotides", "They contain sugar groups that pair with thymine", "Their positively charged amino acids attract the negatively charged phosphate groups"], correct: 4, solution: "Histones are rich in lysine and arginine, which carry a positive charge. These attract the negative phosphate groups along the DNA backbone." },
    { set: 19, question: "Which statement correctly compares euchromatin and heterochromatin?", options: ["Euchromatin is less condensed and generally more transcriptionally active", "Heterochromatin is found only in bacteria", "Euchromatin is more condensed and is always silent", "Heterochromatin contains no DNA", "Both are found only during metaphase"], correct: 0, solution: "Euchromatin is more open, so transcription machinery can reach its genes. Heterochromatin is tightly packed and generally shows low transcription." },
    { set: 19, question: "Why do the circular chromosomes of bacteria not need telomeres?", options: ["Bacteria do not replicate their DNA", "Bacterial DNA contains no phosphate", "A circular molecule has no ends to shorten during replication", "Bacteria use RNA as their genome", "Their chromosomes are protected by histones"], correct: 2, solution: "Telomeres protect the ends of linear chromosomes and limit their loss during replication. A closed circle has no ends, so this problem does not arise." },
    { set: 19, question: "Which feature is typical of prokaryotic genes, but not of most human genes?", options: ["They are copied into mRNA", "They use a genetic code of three-base codons", "They contain long introns", "Several related genes can be organised in one operon", "They are made of DNA"], correct: 3, solution: "In prokaryotes, related genes are often grouped in an operon and transcribed together as one mRNA. Most human genes have their own promoter and contain introns." },
    { set: 19, question: "What is the role of the centromere in a eukaryotic chromosome?", options: ["It protects the chromosome ends from shortening", "It is where the kinetochore assembles and spindle fibres attach", "It is the main site of ribosome production", "It starts transcription of all genes", "It separates DNA from histones"], correct: 1, solution: "The centromere holds sister chromatids together. It is also where the kinetochore forms, allowing spindle fibres to move the chromosome during division." },
    { set: 19, question: "At which stage of the cell cycle are eukaryotic chromosomes most condensed, and easiest to see under a light microscope?", options: ["G1", "S phase", "G2", "Interphase", "Metaphase"], correct: 4, solution: "Chromosomes reach maximum condensation in metaphase. This is why karyotypes are usually prepared from cells in metaphase." },
    { set: 19, question: "Approximately what fraction of the human genome directly codes for proteins?", options: ["Less than 2%", "About 25%", "About 50%", "About 75%", "Almost 100%"], correct: 0, solution: "Exons that code for proteins make up only about 1.5–2% of the human genome. Bacterial genomes, in contrast, consist mostly of coding sequence." },
    /* NEWQ-CELL-DOCS: new questions for chapters with lesson documents (Cell theory and cell size; Cell membrane) */
    { set: 3, question: "Which of the following is NOT part of the classical cell theory?", options: ["The cell is the basic unit of structure and function in living things", "The cell is the smallest unit that shows all the properties of life", "All cells have a true nucleus surrounded by a nuclear envelope", "All cells come from pre-existing cells", "All living organisms are made of one or more cells"], correct: 2, solution: "The three ideas are: organisms are made of one or more cells; the cell is the basic unit of structure and function (the smallest unit with all the properties of life); and cells come from pre-existing cells. Prokaryotic cells have no nucleus, so a nucleus is not part of the theory." },
    { set: 3, question: "Which statement about viruses is correct?", options: ["They are small prokaryotic cells", "They are made of a plasma membrane and cytoplasm", "They are acellular and can multiply only inside a host cell", "They have their own ribosomes and metabolism", "They contain both DNA and RNA"], correct: 2, solution: "A virus is a nucleic acid (DNA or RNA, never both) in a protein capsid. It has no cytoplasm, ribosomes or metabolism, so it is not a cell and can multiply only inside a host cell." },
    { set: 3, question: "Which cell is correctly matched with a feature that makes it an exception to the usual picture of a cell?", options: ["Skeletal muscle fibre: a single small nucleus", "Platelet: a complete cell with a large nucleus", "Mature red blood cell: no nucleus", "Neuron: no cytoplasm", "Egg cell: no plasma membrane"], correct: 2, solution: "A mature red blood cell has no nucleus. A skeletal muscle fibre is a giant cell with many nuclei, and platelets are fragments of large bone marrow cells." },
    { set: 3, question: "A bacterium is 2 µm long and a virus is 100 nm long. How many viruses placed end to end would fit along the bacterium?", options: ["2", "10", "20", "200", "2,000"], correct: 2, solution: "Use the same unit first: 2 µm = 2,000 nm. Then 2,000 ÷ 100 = 20 viruses." },
    { set: 3, question: "How many square micrometres (µm²) are there in 1 square millimetre (mm²)?", options: ["1,000", "10,000", "1,000,000", "1,000,000,000", "1,000,000,000,000"], correct: 2, solution: "1 mm = 1,000 µm, so 1 mm² = 1,000 × 1,000 = 1,000,000 µm². Areas must be squared (and volumes cubed)." },
    { set: 3, question: "A photograph of a cell has a scale bar 25 mm long, labelled 10 µm. The cell in the photograph is 60 mm long. What is its real length?", options: ["2.4 µm", "6 µm", "24 µm", "150 µm", "240 µm"], correct: 2, solution: "25 mm = 25,000 µm, so the magnification is 25,000 ÷ 10 = ×2,500. Real length = 60,000 µm ÷ 2,500 = 24 µm." },
    { set: 3, question: "A bacterium is 2 µm long. How long is its image in a drawing at a magnification of ×5,000?", options: ["10 µm", "1 mm", "2.5 mm", "10 mm", "100 mm"], correct: 3, solution: "Image size = magnification × actual size = 5,000 × 2 µm = 10,000 µm = 10 mm." },
    { set: 3, question: "A cube-shaped cell has a side of 4 µm. What is its surface area to volume ratio?", options: ["0.67 µm⁻¹", "1.5 µm⁻¹", "6 µm⁻¹", "24 µm⁻¹", "96 µm⁻¹"], correct: 1, solution: "Surface area = 6 × 4² = 96 µm². Volume = 4³ = 64 µm³. SA/V = 96 ÷ 64 = 1.5 µm⁻¹ (shortcut: 6 ÷ side = 6 ÷ 4)." },
    { set: 3, question: "A spherical bacterium has a radius of 1 µm and a spherical animal cell has a radius of 10 µm. How do their surface area to volume ratios compare?", options: ["The bacterium's ratio is 10 times lower", "The bacterium's ratio is 10 times higher", "The bacterium's ratio is 100 times higher", "They are equal", "The bacterium's ratio is 1,000 times higher"], correct: 1, solution: "For a sphere SA/V = 3 ÷ r. Bacterium: 3 ÷ 1 = 3 µm⁻¹. Animal cell: 3 ÷ 10 = 0.3 µm⁻¹. The bacterium's ratio is 10 times higher." },
    { set: 3, question: "A cube-shaped cell grows from a side of 2 µm to a side of 6 µm. Which statement is correct?", options: ["Surface area ×27, volume ×9, SA/V rises threefold", "Surface area ×9, volume ×27, SA/V falls to one third", "Surface area ×9, volume ×27, SA/V rises threefold", "Surface area ×6, volume ×6, SA/V unchanged", "Surface area ×3, volume ×9, SA/V unchanged"], correct: 1, solution: "The side is multiplied by 3, so the surface area is multiplied by 3² = 9 and the volume by 3³ = 27. SA/V is divided by 3 (from 3 to 1 µm⁻¹)." },
    { set: 3, question: "Eight cubes of side 1 mm are compared with one cube of side 2 mm. The total volume is the same (8 mm³). How do their surface area to volume ratios compare?", options: ["The eight small cubes have twice the ratio", "The eight small cubes have four times the ratio", "The ratios are equal", "The eight small cubes have half the ratio", "The eight small cubes have eight times the ratio"], correct: 0, solution: "The eight small cubes have a total surface of 8 × 6 = 48 mm², against 24 mm² for the big cube, for the same volume. Their SA/V is 6 against 3: twice as large. Dividing into smaller units increases SA/V." },
    { set: 3, question: "If a shape is enlarged by a factor k in every direction, its surface area to volume ratio:", options: ["is divided by k²", "is multiplied by k", "is divided by k", "does not change", "is multiplied by k²"], correct: 2, solution: "Surface area is multiplied by k² and volume by k³, so SA/V is multiplied by k²/k³ = 1/k: it is divided by k." },
    { set: 3, question: "The time needed for diffusion grows with the square of the distance. If the distance is 10 times greater, the time needed is about:", options: ["10 times longer", "20 times longer", "100 times longer", "1,000 times longer", "the same"], correct: 2, solution: "Time is proportional to distance squared: 10² = 100. Diffusion works well only over cell-sized distances." },
    { set: 3, question: "Compared with a mouse, the liver cells of an elephant are:", options: ["much smaller, to keep a high surface area to volume ratio", "about 10 times bigger", "bigger, because they contain more nuclei", "about 100 times bigger", "about the same size, there are simply many more of them"], correct: 4, solution: "A larger organism has more cells, not bigger cells. Cells stay small because a bigger cell would have a lower surface area to volume ratio." },
    { set: 3, question: "A cell has one circular chromosome, 70S ribosomes and divides by binary fission. It is most likely:", options: ["a white blood cell", "a bacterial cell", "a human liver cell", "a yeast cell", "a plant leaf cell"], correct: 1, solution: "Prokaryotic cells have one circular chromosome, 70S ribosomes and divide by binary fission. Eukaryotic cells have linear chromosomes, 80S ribosomes in the cytoplasm and divide by mitosis." },
    { set: 3, question: "A 70S bacterial ribosome is made of which two subunits?", options: ["30S and 50S", "40S and 60S", "20S and 50S", "30S and 40S", "35S and 35S"], correct: 0, solution: "A 70S ribosome is made of a 30S and a 50S subunit. S values are sedimentation coefficients, not sizes, so they do not add up." },
    { set: 3, question: "Which is the correct order of the steps of binary fission?", options: ["Segregation, septum formation, DNA replication, cytokinesis, elongation", "Elongation, cytokinesis, DNA replication, septum formation, segregation", "Septum formation, DNA replication, elongation, segregation, cytokinesis", "Cytokinesis, DNA replication, segregation, elongation, septum formation", "DNA replication, segregation of the copies, cell elongation, septum formation, cytokinesis"], correct: 4, solution: "The circular chromosome is copied first; the two copies move to opposite ends; the cell elongates; a septum grows inward in the middle; then the cell splits (cytokinesis)." },
    { set: 3, question: "Starting from one bacterium that divides every 20 minutes, how many bacteria are there after 2 hours, if growth is not limited?", options: ["6", "12", "36", "64", "120"], correct: 3, solution: "2 hours = 120 minutes = 6 divisions. The number of cells doubles each time: 2⁶ = 64." },
    { set: 3, question: "Which is the correct order of the lytic cycle of a bacteriophage?", options: ["Attachment, assembly, entry, release, replication", "Entry, attachment, assembly, replication, release", "Assembly, attachment, entry, replication, release", "Attachment, entry of the nucleic acid, replication of viral parts, assembly, release by lysis", "Replication, release, attachment, entry, assembly"], correct: 3, solution: "The phage attaches to the host, injects its nucleic acid, the host machinery copies the viral nucleic acid and makes viral proteins, new viruses are assembled, and the cell bursts (lysis) to release them." },
    { set: 3, question: "In the lysogenic cycle of a virus:", options: ["the virus can never switch to the lytic cycle", "the viral DNA is inserted into the host chromosome as a prophage and is copied each time the host divides", "the virus makes its own ribosomes and grows on its own", "the viral RNA is turned into a capsid by the host membrane", "the host cell bursts immediately and new viruses are released"], correct: 1, solution: "In the lysogenic cycle the viral DNA is inserted into the host chromosome (a prophage) and stays quiet. The host survives and divides. The virus can later switch to the lytic cycle when conditions change." },
    { set: 3, question: "Which term describes the smallest distance between two points that can still be seen as separate?", options: ["Magnification", "Scale", "Resolution", "Contrast", "Staining"], correct: 2, solution: "Resolution (resolving power) is the smallest distance between two points that can still be seen as separate. Magnification only makes the image bigger and does not show more detail." },
    { set: 3, question: "Which microscope gives a three-dimensional view of the surface of a specimen?", options: ["Transmission electron microscope", "Light microscope with stains", "Scanning electron microscope", "Light microscope", "Light microscope at ×1,500"], correct: 2, solution: "The scanning electron microscope (SEM) shows a 3D surface view in black and white. The TEM shows thin slices in 2D, and the light microscope gives a 2D image." },
    { set: 3, question: "Approximately how large is a human egg cell?", options: ["100 nm", "1 µm", "10 µm", "100 µm", "1 cm"], correct: 3, solution: "A human egg is about 0.1 mm, which is 100 µm. It is big because it stores nutrients for the early embryo, and it has a slow metabolism." },
    { set: 3, question: "Why is a red blood cell a biconcave disc?", options: ["It makes the cell heavier so that it sinks in blood", "It reduces the surface area to keep oxygen inside", "It lets the cell swim with a flagellum", "It gives a large surface and a short diffusion path for oxygen", "It leaves room for a large nucleus"], correct: 3, solution: "A flat biconcave shape gives a large surface area compared with the volume and a very short distance for oxygen to diffuse. The cell is also flexible and has no nucleus." },
    { set: 3, question: "Which change would NOT increase the rate of diffusion across a surface?", options: ["A shorter diffusion distance", "A larger surface area", "A steeper concentration gradient", "A thicker diffusion barrier", "A greater difference in concentration"], correct: 3, solution: "Rate of diffusion is proportional to (surface area × concentration difference) ÷ distance. A thicker barrier means a longer distance, which slows diffusion." },
    { set: 3, question: "Which structure is a small extra ring of DNA in a bacterium, often carrying genes for antibiotic resistance?", options: ["Plasmid", "Septum", "Nucleoid", "Capsule", "Flagellum"], correct: 0, solution: "Plasmids are small extra rings of DNA, separate from the main circular chromosome in the nucleoid. They often carry useful genes such as antibiotic resistance." },
    { set: 3, question: "Which structure passes DNA from one bacterium to another during conjugation?", options: ["Flagellum", "Capsule", "Septum", "Fimbria", "Sex pilus"], correct: 4, solution: "Sex pili pass DNA between bacterial cells in conjugation (a form of horizontal gene transfer). Fimbriae only help attachment, and the flagellum is for swimming." },
    { set: 3, question: "Which statement about platelets is correct?", options: ["They are complete cells with a nucleus", "They carry oxygen in the blood", "They are fragments of large cells in the bone marrow", "They are the largest cells in the blood", "They are bacteria that live in blood"], correct: 2, solution: "Platelets (2 to 3 µm) are not complete cells: they are fragments of large cells in the bone marrow." },
    { set: 6, question: "A flaccid plant cell has a pressure potential of 0 MPa and a solute potential of −0.7 MPa. It is placed in pure water. When net movement of water stops, what are the cell's pressure potential (Ψp) and water potential (Ψ)?", options: ["Ψp = −0.7 MPa, Ψ = 0", "Ψp = 0, Ψ = −0.7 MPa", "Ψp = +1.4 MPa, Ψ = +0.7 MPa", "Ψp = +0.7 MPa, Ψ = −0.7 MPa", "Ψp = +0.7 MPa, Ψ = 0"], correct: 4, solution: "Water enters because the cell's Ψ (−0.7 MPa) is lower than that of pure water (0). Turgor pressure rises until Ψp = +0.7 MPa. Then Ψ = −0.7 + 0.7 = 0, equal to the water outside, and the cell is turgid." },
    { set: 6, question: "A plant cell has Ψs = −0.7 MPa and Ψp = +0.4 MPa. It is surrounded by a solution with Ψ = −0.1 MPa. What happens?", options: ["The cell plasmolyses", "Solutes enter the cell until Ψ equals −0.1 MPa", "There is no net movement, because Ψp balances Ψs", "Water leaves the cell, because the solution has a higher Ψ", "Water enters the cell, because the cell's Ψ (−0.3 MPa) is lower than that of the solution"], correct: 4, solution: "The cell's Ψ = −0.7 + 0.4 = −0.3 MPa. Water moves from higher Ψ (−0.1, outside) to lower Ψ (−0.3, inside), so it enters the cell." },
    { set: 6, question: "What is the solute potential of 0.1 M sucrose at 298 K? (Ψs = −iMRT, with R = 0.00831 L·MPa/(mol·K))", options: ["−0.025 MPa", "−0.25 MPa", "−0.50 MPa", "+0.25 MPa", "−2.5 MPa"], correct: 1, solution: "Sucrose does not split, so i = 1. Ψs = −1 × 0.1 × 0.00831 × 298 ≈ −0.25 MPa." },
    { set: 6, question: "Which solution has the more negative solute potential?", options: ["0.1 M sucrose", "0.1 M NaCl, because it gives about twice as many particles", "0.1 M glucose", "They are all equal, because the concentration is the same", "Pure water"], correct: 1, solution: "Solute potential depends on the number of particles. NaCl splits into two ions (i ≈ 2), so 0.1 M NaCl is about twice as negative as 0.1 M sucrose or glucose. Pure water has Ψ = 0." },
    { set: 6, question: "A red blood cell contains about 0.3 M of non-penetrating solutes. It is placed in a solution with 0.6 M of non-penetrating solutes. What happens?", options: ["The solution is isotonic and nothing happens", "The solution is hypotonic and the cell bursts", "The solution is hypertonic and the cell shrivels (crenation)", "The solution is hypertonic and the cell swells", "The solution is hypotonic and the cell shrivels"], correct: 2, solution: "0.6 M is more than 0.3 M, so the solution is hypertonic to the cell. Water leaves the cell and the animal cell shrivels (crenation)." },
    { set: 6, question: "A plant cell is placed in an isotonic solution. It becomes:", options: ["turgid", "crenated", "flaccid", "lysed", "plasmolysed"], correct: 2, solution: "In an isotonic solution there is no net water uptake, so the plant cell loses its firmness and becomes flaccid (the plant wilts). Turgid is the healthy state in a hypotonic solution." },
    { set: 6, question: "A freshwater Paramecium pumps water out of the cell with a contractile vacuole. This is needed because its surroundings are:", options: ["free of solutes, so no osmosis occurs", "isotonic, so water enters and leaves equally", "hypertonic, so water keeps entering", "hypotonic, so water keeps entering", "hypertonic, so water keeps leaving"], correct: 3, solution: "Pond water has less solute than the cell (hypotonic), so water keeps flowing in. A cell without a wall would burst, so the contractile vacuole pumps the water out." },
    { set: 6, question: "How does the osmotic effect of 0.1 M NaCl compare with that of 0.2 M glucose?", options: ["0.1 M NaCl has half the effect", "0.1 M NaCl has about the same effect, because NaCl splits into two ions", "0.1 M NaCl has twice the effect", "0.1 M NaCl has no effect, because it is a salt", "They cannot be compared"], correct: 1, solution: "Osmosis depends on the number of particles. 0.1 M NaCl gives about 0.2 M of particles (Na⁺ and Cl⁻), the same as 0.2 M glucose, which does not split." },
    { set: 6, question: "A vesicle carrying membrane proteins from the Golgi apparatus fuses with the plasma membrane. Which face of the vesicle membrane becomes the outer face of the plasma membrane?", options: ["Only the face that carried no sugar chains", "Neither: the proteins turn over during fusion", "The face that was inside the vesicle (the lumen face)", "The face that was in contact with the cytosol", "Both faces become the outer face"], correct: 2, solution: "When the vesicle fuses, its inside becomes the outside of the cell. The sugar chains, which always face the lumen of the ER and Golgi, therefore end up on the outer surface of the plasma membrane." },
    { set: 6, question: "Which statement about integral membrane proteins is correct?", options: ["They are attached only to the surface by weak bonds", "They are made of phospholipids", "They can never move sideways", "Most are transmembrane proteins, with stretches of nonpolar amino acids inside the lipid core", "They lie only on the outer face of the membrane"], correct: 3, solution: "Integral proteins go into the hydrophobic core. Most cross the whole bilayer, with stretches of about 20 to 30 nonpolar amino acids (often an α helix) inside the lipid. Peripheral proteins are the ones attached to the surface." },
    { set: 6, question: "Which change makes a membrane more fluid at low temperature?", options: ["Tighter packing of the phospholipids", "Removing the kinks by saturating the tails", "More unsaturated fatty acids", "Longer, straighter fatty acid tails", "More saturated fatty acids"], correct: 2, solution: "Unsaturated tails have a kink at each double bond, so they cannot pack tightly and the membrane stays fluid at lower temperatures. Saturated tails are straight and pack tightly, making the membrane stiffer." },
    { set: 6, question: "Which statement about phospholipid movement in a membrane is correct?", options: ["Phospholipids move sideways only at 0 °C", "Phospholipids move only when ATP is used", "Phospholipids cannot move at all, because they are joined by covalent bonds", "Phospholipids slide sideways within their own layer very quickly but rarely flip-flop to the other layer", "Phospholipids flip-flop between the two layers millions of times per second"], correct: 3, solution: "Lipids move sideways within their layer about 10 million times per second, but a flip-flop is rare because the polar head would have to cross the hydrophobic core. The molecules are held by weak interactions, not covalent bonds." },
    { set: 6, question: "In a classic experiment, a mouse cell and a human cell with differently labelled surface proteins were fused. Within about an hour the two labels were mixed over the whole hybrid cell. What does this show?", options: ["The cell wall disappears during fusion", "Mouse and human cells have identical proteins", "Membrane proteins can move sideways through the membrane", "Membrane lipids never move", "Membrane proteins are made in the nucleus"], correct: 2, solution: "The mixing of the two colours shows that membrane proteins can drift sideways through the fluid membrane." },
    { set: 6, question: "A membrane receptor binds a hormone and passes the message to the inside of the cell. Which function of membrane proteins is this?", options: ["Enzymatic activity", "Attachment to the cytoskeleton", "Signal transduction", "Intercellular joining", "Transport"], correct: 2, solution: "A receptor whose shape fits a chemical messenger changes when the messenger binds and passes the message into the cell: this is signal transduction." },
    { set: 6, question: "HIV needs a second surface protein, in addition to CD4, to enter immune cells. Which one?", options: ["Aquaporin", "CFTR", "CCR5", "GLUT1", "Fibronectin"], correct: 2, solution: "HIV binds CD4 and then needs the co-receptor CCR5. People with no CCR5 are protected, and the drug maraviroc blocks CCR5." },
    { set: 6, question: "Which junction seals the space between neighbouring epithelial cells and stops fluid from leaking between them?", options: ["Plasmodesma", "Desmosome", "Gap junction", "Tight junction", "Cytoplasmic bridge"], correct: 3, solution: "Tight junctions seal, desmosomes hold, gap junctions communicate. Plasmodesmata are the channels between plant cells." },
    { set: 6, question: "Which junction allows ions and small molecules to pass between heart muscle cells, so that the cells contract together?", options: ["Hemidesmosome", "Plasmodesma", "Tight junction", "Desmosome", "Gap junction"], correct: 4, solution: "Gap junctions are pores built from connexin proteins. They let ions and small molecules pass, so electrical signals spread through heart muscle." },
    { set: 6, question: "Which structure joins the cytoplasm of neighbouring plant cells through their cell walls?", options: ["Gap junction", "Desmosome", "Tight junction", "Plasmodesma", "Integrin"], correct: 3, solution: "Plasmodesmata are channels through the cell walls of plants. Plants have no desmosomes or gap junctions." },
    { set: 6, question: "Which extracellular protein links collagen fibres to integrins?", options: ["Ankyrin", "Fibronectin", "Connexin", "Spectrin", "Claudin"], correct: 1, solution: "In the extracellular matrix, fibronectin links collagen to integrins, the membrane proteins that connect the matrix to the cytoskeleton." },
    { set: 6, question: "A proton pump in the plasma membrane of a plant cell builds an H⁺ gradient. How does the H⁺/sucrose cotransporter use it?", options: ["Sucrose is pumped out of the cell", "H⁺ is pumped out again, using ATP at the cotransporter", "H⁺ flows back in down its gradient and carries sucrose in with it, even against the sucrose gradient", "Sucrose diffuses through the lipid bilayer", "The cotransporter makes ATP"], correct: 2, solution: "ATP was spent by the proton pump to build the gradient. The cotransporter then lets H⁺ flow back down its gradient and sucrose can only cross together with H⁺: this is secondary active transport." },
    { set: 6, question: "Which of the following is an example of secondary active transport?", options: ["Na⁺/K⁺ ATPase", "Simple diffusion of O₂", "Na⁺/glucose cotransport", "Osmosis of water", "Ca²⁺ ATPase"], correct: 2, solution: "Primary active transport uses ATP directly (the pumps are ATPases). Secondary active transport uses a gradient built by a primary pump: Na⁺/glucose and H⁺/sucrose cotransport." },
    { set: 6, question: "The H⁺/K⁺ pump of the stomach moves two ions in opposite directions. It is a(n):", options: ["antiporter", "uniporter", "symporter", "channel", "aquaporin"], correct: 0, solution: "An antiporter moves two substances in opposite directions (also the Na⁺/K⁺ pump). A symporter moves two in the same direction, and a uniporter moves one." },
    { set: 6, question: "As the concentration of a solute increases, carrier-mediated transport levels off at a maximum rate, while simple diffusion keeps rising. What causes the levelling off?", options: ["The concentration gradient becomes zero", "All the carriers are busy (saturated)", "The solute becomes nonpolar", "The membrane runs out of ATP", "The carriers are destroyed"], correct: 1, solution: "A cell has a limited number of carriers, and each handles only a limited number of molecules per second. When every carrier is busy, the rate reaches a maximum (Vmax)." },
    { set: 6, question: "Why is the Na⁺/K⁺ pump electrogenic?", options: ["It moves 2 Na⁺ out for every 3 K⁺ in", "It moves equal numbers of Na⁺ and K⁺ in the same direction", "It builds a proton gradient", "It uses light energy", "It moves 3 Na⁺ out for every 2 K⁺ in, so one net positive charge leaves per cycle"], correct: 4, solution: "Each cycle moves 3 Na⁺ out and 2 K⁺ in, so one more positive charge leaves than enters. This helps to make the inside of the cell negative." },
    { set: 6, question: "In a resting animal cell, which statement describes the two forces acting on K⁺?", options: ["Both pull K⁺ into the cell", "The concentration gradient pulls K⁺ in, but the negative inside pushes it out", "Both push K⁺ out of the cell", "No force acts on K⁺ at rest", "The concentration gradient pushes K⁺ out, but the negative inside pulls it in"], correct: 4, solution: "K⁺ is more concentrated inside, so its concentration gradient pushes it out. The inside is negative, which pulls the positive K⁺ in. The two forces together make the electrochemical gradient." },
    { set: 6, question: "Inside a cell [Na⁺] = 14 mM and outside it is 140 mM. What is the equilibrium potential for Na⁺ at 37 °C? (E = 61.5/z × log10([ion]out / [ion]in))", options: ["−95 mV", "−61.5 mV", "0 mV", "+61.5 mV", "+123 mV"], correct: 3, solution: "z = +1 and [out]/[in] = 140/14 = 10, so log10(10) = 1. E = 61.5 × 1 = +61.5 mV." },
    { set: 6, question: "In a growing cell, how do exocytosis and endocytosis compare?", options: ["Exocytosis adds more membrane than endocytosis removes, so the plasma membrane grows", "They are exactly equal", "Endocytosis adds more membrane than exocytosis removes", "Neither changes the amount of plasma membrane", "Only endocytosis changes the plasma membrane"], correct: 0, solution: "Exocytosis adds membrane to the surface and endocytosis removes it. In a cell that is not growing the two balance. In a growing cell exocytosis adds more, so the plasma membrane gets larger." },
    { set: 6, question: "Receptors in the plasma membrane bind one specific substance and cluster in a coated pit. The pit pinches off as a coated vesicle. This process is:", options: ["facilitated diffusion", "pinocytosis", "phagocytosis", "receptor-mediated endocytosis", "exocytosis"], correct: 3, solution: "Receptor-mediated endocytosis is selective: receptors bind one substance and collect it in coated pits. An example is the uptake of cholesterol carried in LDL particles." }
  ];

  var bio = subjects.find(function (s) { return s.id === 'biology'; });
  if (bio && bio.chapters) bio.chapters.push({ id: 'bio-added-questions', name: 'Added questions', questions: Q });
})();
